public static void main(String[] args) {
    Scanner scanner = new Scanner(System.in);

    int n = scanner.nextInt();

    String text;
    String gridA[][] = new String[n][];
    String gridB[][] = new String[n][];
    int row = 0;
    int column = 0;
    String strLineA[] = new String[n];
    String strLineB[] = new String[n];

    int count = n;

    while (count > 0) {
        text = scanner.next();
        strLineA[n - count] = text; 
        gridA[n - count] = text.split("");
        count = count - 1;
    }

    count = n;

    while (count > 0) {
        text = scanner.next();
        strLineB[n - count] = text;
        gridB[n - count] = text.split("");
        count = count - 1;
    }

    scanner.close();
    count = n;

    while (count > 0) {
        if (!strLineA[n - count].equals(strLineB[n - count])) {
            row = n - count + 1;
            break;
        }
        count = count - 1;
    }

    count = n;

    while (count > 0) {
        if (!gridA[row - 1][n - count].equals(gridB[row - 1][n - count])) {
            column = n - count + 1;
            break;
        }
        count = count - 1;
    }

    System.out.println(row + " " + column);
}
